	@override String get eula_updated => 'Cập nhật lần cuối: Tháng 4/2026';
	@override String eula_intro({required Object brand, required Object app}) => 'Thỏa thuận này là hợp đồng pháp lý giữa bạn (Người dùng) và ${brand} (Chúng tôi) về việc sử dụng ứng dụng di động ${app}. Bằng việc cài đặt hoặc sử dụng ứng dụng, bạn đồng ý tuân thủ các điều khoản sau:';
	@override String get eula_p1_title => '1. Cấp phép sử dụng';
	@override String eula_p1_desc({required Object app}) => 'Chúng tôi cấp cho bạn một giấy phép giới hạn, không độc quyền, không thể chuyển nhượng và có thể thu hồi để tải xuống, cài đặt và sử dụng ${app} trên các thiết bị di động thuộc quyền sở hữu của bạn, phục vụ cho mục đích cá nhân và không thương mại.';
	@override String get eula_p2_title => '2. Quyền sở hữu trí tuệ';
	@override String eula_p2_desc1({required Object app}) => 'Toàn bộ quyền, danh nghĩa và lợi ích đối với ứng dụng ${app}, bao gồm nhưng không giới hạn ở:';
	@override String get eula_p2_item1 => '• Công nghệ: Các thuật toán tính toán mức độ nỗ lực (RPE), logic đánh giá độ sẵn sàng của cơ bắp (Muscle Readiness).';
	@override String eula_p2_item2({required Object brand, required Object app}) => '• Thiết kế: Giao diện người dùng (UI), trải nghiệm người dùng (UX), logo ${brand} và biểu tượng ${app}.';
	@override String get eula_p2_item3 => '• Nội dung: Các gói tập mẫu, dữ liệu hướng dẫn và cấu trúc biểu đồ.';
	@override String eula_p2_desc2({required Object brand}) => 'Tất cả đều là tài sản trí tuệ độc quyền của ${brand}. Mọi hành vi sao chép hoặc sử dụng trái phép đều vi phạm pháp luật.';
	@override String get eula_p3_title => '3. Các hành vi bị nghiêm cấm';
	@override String get eula_p3_desc1 => 'Bạn cam kết không thực hiện và không cho phép bên thứ ba thực hiện các hành vi sau:';
	@override String get eula_p3_item1 => '• Dịch ngược (reverse engineer), tháo rời hoặc tìm cách trích xuất mã nguồn của ứng dụng.';
	@override String eula_p3_item2({required Object app}) => '• Sao chép các công thức tính toán và logic phục hồi của ${app} để xây dựng sản phẩm cạnh tranh.';
	@override String get eula_p3_item3 => '• Sử dụng ứng dụng cho bất kỳ mục đích bất hợp pháp hoặc vi phạm các tuyên bố về an toàn y tế.';
	@override String get eula_p4_title => '4. Dữ liệu và Quyền riêng tư';
	@override String get eula_p4_desc => 'Việc sử dụng ứng dụng của bạn cũng tuân theo Chính sách bảo mật của chúng tôi. Bạn hiểu rằng dữ liệu sẽ được lưu trữ cục bộ (SQLite) và đồng bộ hóa qua dịch vụ đám mây để đảm bảo trải nghiệm tốt nhất. Bạn có quyền yêu cầu xóa tài khoản và toàn bộ dữ liệu liên quan bất cứ lúc nào.';
	@override String get eula_p5_title => '5. Giới hạn trách nhiệm và Miễn trừ y tế';
	@override String eula_p5_item1({required Object app}) => '• Tính chất tham khảo: ${app} cung cấp các chỉ số dựa trên dữ liệu đầu vào của bạn và không thay thế cho lời khuyên y tế chuyên nghiệp.';
	@override String get eula_p5_item2 => '• Rủi ro: Bạn tự chịu trách nhiệm về mọi rủi ro chấn thương phát sinh trong quá trình tập luyện theo gợi ý của ứng dụng.';
	@override String get eula_p5_item3 => '• Dịch vụ: Vì đây là phiên bản miễn phí, chúng tôi không chịu trách nhiệm về các sự cố mất mát dữ liệu do lỗi kỹ thuật hoặc sự cố bất khả kháng.';
	@override String get eula_p6_title => '6. Chấm dứt thỏa thuận';
	@override String get eula_p6_desc => 'Thỏa thuận này có hiệu lực cho đến khi bạn hoặc chúng tôi chấm dứt. Chúng tôi có quyền tạm ngừng hoặc khóa quyền truy cập ứng dụng của bạn nếu phát hiện vi phạm các điều khoản này mà không cần thông báo trước.';
}

