			case 'equipment.bodyweight': return 'Bodyweight';
			case 'equipment.barbell': return 'Barbell';
			case 'equipment.dumbbell': return 'Dumbbell';
			case 'equipment.machine': return 'Machine';
			case 'equipment.cable': return 'Cable';
			case 'equipment.kettlebell': return 'Kettlebell';
			case 'equipment.band': return 'Resistance Band';
			case 'equipment.rope': return 'Jumping Rope';
			case 'equipment.other': return 'Other';
			case 'exercises.type_weight_reps': return 'Weight & Reps';
			case 'exercises.type_time_only': return 'Time Only';
			case 'exercises.type_cardio_distance': return 'Distance & Time';
			case 'exercises.type_cardio_steps': return 'Steps & Time';
			case 'exercises.type_reps_only': return 'Reps Only';
			case 'exercises.name_squat': return 'Bodyweight Squat';
			case 'exercises.desc_squat': return '1. Take a deep breath and brace your core. Hinge your hips back and bend your knees as if sitting in an invisible chair.\n2. Lower until your hip crease is below the top of your knees (if mobility allows). Keep your weight evenly distributed across your whole foot.\n3. Exhale, drive through the floor, squeeze your glutes and quads to stand back up.';
			case 'exercises.name_arnold_press': return 'Arnold Press';
			case 'exercises.desc_arnold_press': return '1. Hold dumbbells at shoulder height with palms facing you.\n2. Exhale and press the dumbbells overhead. While pressing, smoothly rotate your wrists so your palms face forward at the top.\n3. Inhale, lower the dumbbells, and reverse the rotation back to the starting position.';
			case 'exercises.name_australian_pull_up': return 'Australian Pull-Up';
			case 'exercises.desc_australian_pull_up': return '1. Grip a low bar and position your body in a straight line from heels to head (like a reverse plank).\n2. Exhale, pull your shoulder blades back, and row your chest up to touch the bar.\n3. Squeeze at the top for 1 second, then inhale and slowly lower yourself until arms are fully extended.';
			case 'exercises.name_bench_press': return 'Barbell Bench Press';
			case 'exercises.desc_bench_press': return '1. Unrack the barbell and hold it directly over your mid-chest.\n2. Inhale and lower the bar under control until it lightly touches your mid-chest. Do not bounce the bar.\n3. Pause briefly, then exhale, drive your feet into the floor, and press the bar back up in a slight arc toward your head.';
			case 'exercises.name_barbell_curl': return 'Barbell Bicep Curl';
			case 'exercises.desc_barbell_curl': return '1. Keep your back straight, chest up, and elbows pinned to your sides.\n2. Exhale, squeeze your biceps, and curl the barbell in an arc toward your chest/chin.\n3. Inhale and slowly lower the bar back to the starting position to fully stretch the biceps.';
			case 'exercises.name_hip_thrust': return 'Barbell Hip Thrust';
			case 'exercises.desc_hip_thrust': return '1. Rest your upper back on a bench with the barbell across your hips. Position your feet so your shins are vertical at the top of the movement.\n2. Inhale, brace your core, and tuck your chin slightly.\n3. Exhale, drive through your heels, and squeeze your glutes to thrust the bar up until your thighs and torso are parallel to the floor.\n4. Hold the top for 1-2 seconds, then slowly lower.';
			case 'exercises.name_overhead_press': return 'Overhead Press';
			case 'exercises.desc_overhead_press': return '1. Take a deep breath, brace your core, and squeeze your glutes.\n2. Exhale and press the bar straight up. As the bar clears your face, slightly push your head forward to lock out the bar directly over your mid-foot.\n3. Inhale and lower the bar back to the front rack position under control.';
			case 'exercises.name_barbell_row': return 'Barbell Row';
			case 'exercises.desc_barbell_row': return '1. Bend over while keeping your back naturally straight. Brace your core and look slightly down.\n2. Exhale, retract your shoulder blades, and pull the bar toward your belly button.\n3. Keep your elbows relatively close to your body. Squeeze at the top.\n4. Inhale and lower the bar slowly until your arms are fully extended.';
			case 'exercises.name_barbell_squat': return 'Barbell Squat';
			case 'exercises.desc_barbell_squat': return '1. Rest the bar on your upper back. Take a deep breath into your belly to create intra-abdominal pressure (bracing).\n2. Push your hips back and bend your knees to squat down. Go as deep as your mobility allows while keeping a straight spine.\n3. Drive hard through the floor, exhale forcefully, and stand back up.';
			case 'exercises.name_bench_dips': return 'Bench Dips';
			case 'exercises.desc_bench_dips': return '1. Place your hands on the edge of a bench and slide your hips off. Keep your arms straight.\n2. Inhale and slowly bend your elbows to lower your body until your upper arms are parallel to the floor.\n3. Exhale and push through your palms using your triceps to return to the start.';
			case 'exercises.name_bicycle_crunches': return 'Bicycle Crunches';
			case 'exercises.desc_bicycle_crunches': return '1. Lie flat with hands behind your head and legs elevated.\n2. Exhale, extend your right leg out straight, and twist your torso to bring your right elbow toward your left knee.\n3. Inhale through the center, then exhale and switch sides in a continuous pedaling motion.';
			case 'exercises.name_bulgarian_split_squat': return 'Bulgarian Split Squat';
			case 'exercises.desc_bulgarian_split_squat': return '1. Rest your rear foot on a bench. Keep your torso upright.\n2. Inhale and slowly drop your hips by bending both knees until your front thigh is parallel to the floor (rear knee almost touching the ground).\n3. Exhale and drive through your front heel to push back up.';
			case 'exercises.name_burpees': return 'Burpees';
			case 'exercises.desc_burpees': return '1. Drop into a squat position and place your hands on the floor.\n2. Jump both feet back into a high plank position.\n3. Perform one push-up (optional).\n4. Jump your feet back into the squat, then explosively jump vertically with your hands reaching overhead.';
			case 'exercises.name_cable_crunch': return 'Cable Crunch';
			case 'exercises.desc_cable_crunch': return '1. Kneel facing the cable machine, holding the rope attachment behind your neck. Keep your hips locked.\n2. Exhale and crunch downward by flexing your spine, driving your elbows toward your thighs.\n3. Squeeze your abs for 1 second at the bottom.\n4. Inhale and slowly release the weight back up.';
			case 'exercises.name_cable_kickback': return 'Cable Glute Kickback';
			case 'exercises.desc_cable_kickback': return '1. Attach the ankle strap and hold onto the machine for balance. Brace your core.\n2. Exhale and squeeze your glutes to kick the working leg back and up in an arc.\n3. Hold the peak contraction for 1 second.\n4. Inhale and control the weight as you bring your leg back.';
			case 'exercises.name_cable_lateral_raise': return 'Cable Lateral Raise';
			case 'exercises.desc_cable_lateral_raise': return '1. Stand next to a low pulley and grab the D-handle with your outside hand.\n2. With a slight bend in your elbow, exhale and raise your arm out to the side until it\'s parallel to the floor.\n3. Hold for a brief second, then inhale and lower slowly.';
			case 'exercises.name_chin_up': return 'Chin-Up';
			case 'exercises.desc_chin_up': return '1. Grab the bar with an underhand (supinated) grip. Hang with arms fully extended.\n2. Exhale, engage your lats and biceps, and pull your body up until your chin clears the bar.\n3. Inhale and lower yourself under control back to a dead hang.';
			case 'exercises.name_close_grip_pulldown': return 'Close-Grip Lat Pulldown';
			case 'exercises.desc_close_grip_pulldown': return '1. Grab the V-bar attachment and slightly puff your chest out.\n2. Exhale and pull the bar down toward your mid-chest. Keep your elbows tucked close to your sides.\n3. Squeeze your lats at the bottom, then inhale and slowly let the bar back up to get a deep stretch.';
			case 'exercises.name_crunch': return 'Crunch';
			case 'exercises.desc_crunch': return '1. Lie on your back with knees bent. Inhale and engage your core.\n2. Slowly curl your head, neck, and upper back off the floor. Keep your lower back pressed into the mat.\n3. Hold the contraction for 1 second and exhale sharply. Inhale as you lower back down.';
			case 'exercises.name_indoor_cycling': return 'Indoor Cycling';
			case 'exercises.desc_indoor_cycling': return '1. Start pedaling at a moderate pace to warm up.\n2. Keep your core slightly engaged to stabilize your upper body and maintain a smooth, circular pedal stroke.\n3. Adjust the resistance and speed based on your workout protocol.';
			case 'exercises.name_deadlift': return 'Barbell Deadlift';
			case 'exercises.desc_deadlift': return '1. Stand with shins close to the bar. Hinge down, grip the bar, puff your chest out, and engage your lats.\n2. Take a deep breath (brace). Drive your legs into the floor and pull your torso up simultaneously.\n3. Keep the bar dragging up your shins and thighs. Lock out your hips and squeeze your glutes at the top. Exhale.\n4. Hinge your hips back first to lower the bar to the floor.';
			case 'exercises.name_decline_bench_press': return 'Decline Barbell Bench Press';
			case 'exercises.desc_decline_bench_press': return '1. Lie on a decline bench. Unrack the bar and hold it straight over your lower chest.\n2. Inhale and slowly lower the bar until it lightly touches your lower chest.\n3. Exhale and press the bar back up to the starting position.';
			case 'exercises.name_decline_push_up': return 'Decline Push-Up';
			case 'exercises.desc_decline_push_up': return '1. Place your feet on an elevated box or bench so your body forms a downward slope.\n2. Inhale and lower your chest toward the floor, keeping your elbows tucked at a 45-degree angle.\n3. Exhale and push back up to fully extended arms.';
			case 'exercises.name_diamond_push_up': return 'Diamond Push-Up';
			case 'exercises.desc_diamond_push_up': return '1. Form a diamond shape with your thumbs and index fingers placed directly under your chest.\n2. Inhale, lower your body until your chest nearly touches your hands. Keep your elbows tucked tight to your ribs.\n3. Exhale and forcefully push back up using your triceps.';
			case 'exercises.name_chest_dips': return 'Chest Dips';
			case 'exercises.desc_chest_dips': return '1. On parallel bars, lean your torso forward about 30 degrees to target the chest.\n2. Inhale and lower your body until your shoulders drop below your elbows (feel the stretch in your lower chest).\n3. Exhale and push through your palms to return to the top.';
			case 'exercises.name_dumbbell_bench_press': return 'Dumbbell Bench Press';
			case 'exercises.desc_dumbbell_bench_press': return '1. Lie flat on a bench, pressing dumbbells straight up over your chest.\n2. Inhale and lower the dumbbells to the sides of your chest. Flare your elbows out at roughly a 45 to 60-degree angle.\n3. Get a deep stretch, then exhale and press the weights back up.';
			case 'exercises.name_dumbbell_row': return 'Dumbbell Row';
			case 'exercises.desc_dumbbell_row': return '1. Bend over keeping your back straight. Let the dumbbells hang down.\n2. Exhale and pull the dumbbells up toward your hips, driving your elbows to the ceiling.\n3. Squeeze your shoulder blades together at the top. Inhale and lower slowly.';
			case 'exercises.name_dumbbell_curl': return 'Dumbbell Curl';
			case 'exercises.desc_dumbbell_curl': return '1. Keep your upper arms locked in place against your sides.\n2. Exhale and curl the dumbbells up toward your shoulders.\n3. Squeeze your biceps hard at the top, then inhale and lower under control.';
			case 'exercises.name_dumbbell_deadlift': return 'Dumbbell Deadlift';
			case 'exercises.desc_dumbbell_deadlift': return '1. Hold dumbbells by your sides. Inhale, brace your core, hinge your hips back, and bend your knees to lower the weights.\n2. Drive your feet into the ground to pull the weights back up.\n3. Lock your hips and squeeze your glutes at the top. Exhale.';
			case 'exercises.name_dumbbell_fly': return 'Dumbbell Fly';
			case 'exercises.desc_dumbbell_fly': return '1. Lie on a bench, pressing dumbbells straight up. Keep a slight bend in your elbows.\n2. Inhale and lower your arms out to the sides in a wide arc until you feel a deep stretch in your chest.\n3. Exhale and hug the weights back to the top following the same arc.';
			case 'exercises.name_dumbbell_lateral_raise': return 'Dumbbell Lateral Raise';
			case 'exercises.desc_dumbbell_lateral_raise': return '1. Stand with a slight bend in your elbows.\n2. Exhale and raise the dumbbells out to the sides (like pouring water from a pitcher) until your arms are parallel to the floor.\n3. Inhale and lower the weights back down slowly without losing tension.';
			case 'exercises.name_dumbbell_lunges': return 'Dumbbell Lunge';
			case 'exercises.desc_dumbbell_lunges': return '1. Hold dumbbells by your sides. Inhale and take a step forward.\n2. Drop your hips straight down until both knees form a 90-degree angle.\n3. Exhale and push off your front foot to return to the starting position.';
			case 'exercises.name_dumbbell_rdl': return 'Dumbbell Romanian Deadlift';
			case 'exercises.desc_dumbbell_rdl': return '1. Stand tall holding dumbbells in front of your thighs. Keep a slight bend in your knees.\n2. Inhale, push your hips straight back, and glide the weights down your legs until you feel a deep hamstring stretch.\n3. Exhale, squeeze your glutes, and push your hips forward to stand back up.';
			case 'exercises.name_dumbbell_reverse_fly': return 'Dumbbell Reverse Fly';
			case 'exercises.desc_dumbbell_reverse_fly': return '1. Bend over so your torso is almost parallel to the floor. Keep a slight bend in your elbows.\n2. Exhale and raise the dumbbells out to your sides like spreading wings.\n3. Squeeze your rear delts at the top, then inhale and lower slowly.';
			case 'exercises.name_dumbbell_shoulder_press': return 'Dumbbell Shoulder Press';
			case 'exercises.desc_dumbbell_shoulder_press': return '1. Sit with chest up, holding dumbbells at shoulder level. Exhale and press them overhead.\n2. Bring the weights close together at the top without clanking them.\n3. Inhale and slowly lower them back down to ear/shoulder level.';
			case 'exercises.name_dumbbell_shrugs': return 'Dumbbell Shrug';
			case 'exercises.desc_dumbbell_shrugs': return '1. Stand tall with dumbbells hanging naturally by your sides.\n2. Exhale and shrug your shoulders straight up toward your ears.\n3. Hold the top contraction for 1 second.\n4. Inhale and lower your shoulders all the way down to stretch your traps.';
			case 'exercises.name_face_pull': return 'Face Pull';
			case 'exercises.desc_face_pull': return '1. Attach a rope to a high pulley. Pull the rope toward your forehead.\n2. As you pull, pull the handles apart and rotate your wrists up, driving your elbows back past your ears.\n3. Squeeze your shoulder blades for 1 second. Inhale and slowly return.';
			case 'exercises.name_glute_bridge': return 'Glute Bridge';
			case 'exercises.desc_glute_bridge': return '1. Lie on your back with knees bent. Inhale and brace your core.\n2. Exhale, drive through your heels, and squeeze your glutes to push your hips up until your body forms a straight line.\n3. Hold for 1-2 seconds at the top. Inhale and slowly lower your hips.';
			case 'exercises.name_goblet_squat': return 'Goblet Squat';
			case 'exercises.desc_goblet_squat': return '1. Hold a dumbbell vertically against your chest. Inhale and brace your core.\n2. Push your hips back and squat down, letting your elbows drop between your knees.\n3. Exhale, drive through your heels, and stand back up.';
			case 'exercises.name_hammer_curl': return 'Hammer Curl';
			case 'exercises.desc_hammer_curl': return '1. Hold dumbbells with a neutral grip (palms facing each other). Keep upper arms fixed to your sides.\n2. Exhale and curl the weights up toward your shoulders, maintaining the neutral grip.\n3. Inhale and slowly lower the weights down.';
			case 'exercises.name_hanging_leg_raise': return 'Hanging Leg Raise';
			case 'exercises.desc_hanging_leg_raise': return '1. Hang from a pull-up bar. Brace your core tightly.\n2. Exhale and raise your legs straight in front of you until they are parallel to the floor (or higher).\n3. Hold for 1 second, then inhale and lower them with control.';
			case 'exercises.name_high_knees': return 'High Knees';
			case 'exercises.desc_high_knees': return '1. Run in place, driving one knee up to hip level at a time.\n2. Alternate your legs as fast as possible.\n3. Pump your arms rhythmically, keeping your chest up and core engaged.';
			case 'exercises.name_low_to_high_fly': return 'High-to-Low Cable Fly';
			case 'exercises.desc_low_to_high_fly': return '1. Stand between high pulleys. Open your arms with a slight bend in your elbows.\n2. Exhale and pull the handles down and across your body toward your hips.\n3. Squeeze your chest for 1 second at the bottom, then inhale and slowly open your arms.';
			case 'exercises.name_hyperextensions': return 'Back Extension';
			case 'exercises.desc_hyperextensions': return '1. Lock yourself into a back extension bench. Inhale and bend forward at the hips until your torso is vertical to the floor.\n2. Exhale and use your lower back and glutes to pull your torso up until it forms a straight line with your legs.\n3. Hold the top for 1 second, then inhale and slowly lower back down.';
			case 'exercises.name_incline_barbell_press': return 'Incline Barbell Bench Press';
			case 'exercises.desc_incline_barbell_press': return '1. Lie on an incline bench (30-45 degrees). Unrack the bar and hold it over your upper chest.\n2. Inhale and lower the bar under control until it lightly touches your upper chest/collarbone.\n3. Exhale and press the bar straight back up to the starting position.';
			case 'exercises.name_incline_dumbbell_fly': return 'Incline Dumbbell Fly';
			case 'exercises.desc_incline_dumbbell_fly': return '1. Lie on an incline bench, pressing dumbbells straight up. Keep a slight bend in your elbows.\n2. Inhale and open your arms out to the sides until you feel a deep stretch in your upper chest.\n3. Exhale and hug the weights back to the top following the same path.';
			case 'exercises.name_incline_dumbbell_press': return 'Incline Dumbbell Press';
			case 'exercises.desc_incline_dumbbell_press': return '1. Lie on an incline bench and press dumbbells up over your upper chest.\n2. Inhale and lower the dumbbells to the sides. Flare your elbows out at a 45-degree angle.\n3. Exhale, squeeze your upper chest, and press the weights back up, bringing them close together at the top.';
			case 'exercises.name_incline_push_up': return 'Incline Push-Up';
			case 'exercises.desc_incline_push_up': return '1. Place your hands on an elevated box or bench. Keep your body in a straight line.\n2. Inhale and lower your chest toward the box, keeping your elbows tucked at a 45-degree angle.\n3. Exhale and forcefully push back up to straight arms.';
			case 'exercises.name_jump_rope': return 'Jump Rope';
			case 'exercises.desc_jump_rope': return '1. Use your wrists to swing the rope over your head.\n2. Hop lightly on the balls of your feet just enough to clear the rope.\n3. Maintain a continuous rhythm and breathe steadily.';
			case 'exercises.name_jumping_jacks': return 'Jumping Jacks';
			case 'exercises.desc_jumping_jacks': return '1. Jump up and spread your legs wider than shoulder-width apart.\n2. Simultaneously swing your arms up in an arc over your head.\n3. Jump again to return your feet together and lower your arms continuously.';
			case 'exercises.name_lat_pulldown': return 'Lat Pulldown';
			case 'exercises.desc_lat_pulldown': return '1. Sit at the machine, lean back slightly (10 degrees), and puff your chest out.\n2. Exhale and pull the bar down toward your upper chest, driving your elbows down and back.\n3. Squeeze your lats, then inhale and let the bar rise back up until your arms are fully extended.';
			case 'exercises.name_leg_extension': return 'Leg Extension';
			case 'exercises.desc_leg_extension': return '1. Sit on the machine with your back flat against the pad.\n2. Exhale and use your quads to extend your legs fully straight.\n3. Squeeze your quads for 1-2 seconds at the top, then inhale and lower the weight slowly.';
			case 'exercises.name_leg_press': return 'Leg Press';
			case 'exercises.desc_leg_press': return '1. Sit in the leg press machine and place your feet on the sled. Inhale and slowly bend your knees to lower the weight toward your chest.\n2. Lower until your knees are at a 90-degree angle.\n3. Exhale and drive through your heels to push the sled back to the starting position.';
			case 'exercises.name_lying_leg_curl': return 'Lying Leg Curl';
			case 'exercises.desc_lying_leg_curl': return '1. Lie face down on the machine, keeping your hips pressed firmly into the pad.\n2. Exhale and curl the pad up toward your glutes as far as possible using your hamstrings.\n3. Hold the peak contraction for 1 second. Inhale and lower the weight slowly without letting the plates touch.';
			case 'exercises.name_lying_leg_raise': return 'Lying Leg Raise';
			case 'exercises.desc_lying_leg_raise': return '1. Lie flat on your back, pressing your lower back firmly into the floor.\n2. Exhale and raise both legs straight up until they are perpendicular to the ceiling.\n3. Inhale and slowly lower them until they are a few inches above the floor, then repeat.';
			case 'exercises.name_machine_chest_press': return 'Machine Chest Press';
			case 'exercises.desc_machine_chest_press': return '1. Sit in the machine and grip the handles firmly. Inhale deeply.\n2. Exhale and press the handles forward until your arms are nearly fully extended.\n3. Inhale and slowly let the handles return to the starting position, feeling the stretch in your chest.';
			case 'exercises.name_mountain_climbers': return 'Mountain Climbers';
			case 'exercises.desc_mountain_climbers': return '1. Start in a high plank push-up position.\n2. Quickly drive your right knee toward your chest, return it, and immediately drive your left knee up.\n3. Keep your core tight and hips stable as you alternate legs quickly.';
			case 'exercises.name_one_arm_row': return 'Single Arm Dumbbell Row';
			case 'exercises.desc_one_arm_row': return '1. Support one knee and one hand on a bench. Hold a dumbbell with your free hand.\n2. Exhale and pull the dumbbell up to your side, driving your elbow high and back.\n3. Squeeze your back at the top. Inhale and lower the weight to fully stretch the shoulder blade.';
			case 'exercises.name_overhead_triceps_extension': return 'Overhead Triceps Extension';
			case 'exercises.desc_overhead_triceps_extension': return '1. Hold one dumbbell straight overhead with both hands. Keep your upper arms pinned near your ears.\n2. Inhale and bend your elbows to lower the weight behind your head until your triceps stretch.\n3. Exhale and extend your elbows to push the weight back to the top.';
			case 'exercises.name_pike_push_up': return 'Pike Push-Up';
			case 'exercises.desc_pike_push_up': return '1. Get into an inverted V position with your hips high in the air.\n2. Inhale and lower the crown of your head toward the floor, forming a triangle with your hands.\n3. Exhale and push through your shoulders and triceps back to the start.';
			case 'exercises.name_plank': return 'Plank';
			case 'exercises.desc_plank': return '1. Support your body on your forearms and toes, forming a straight line from head to heels.\n2. Actively brace your core, glutes, and quads.\n3. Hold this static position while breathing steadily.';
			case 'exercises.name_pull_up': return 'Pull-Up';
			case 'exercises.desc_pull_up': return '1. Grip the bar with an overhand (pronated) grip. Brace your core to prevent swinging.\n2. Exhale and pull yourself up by driving your elbows down to the floor.\n3. Pull until your chin clears the bar. Inhale and slowly lower yourself to a full dead hang.';
			case 'exercises.name_push_up': return 'Push-Up';
			case 'exercises.desc_push_up': return '1. Start in a high plank position. Keep your body in a perfectly straight line.\n2. Inhale and bend your elbows to lower your body until your chest is about an inch from the floor.\n3. Exhale and press through your chest and triceps to return to the starting position.';
			case 'exercises.name_reverse_pec_deck': return 'Reverse Pec Deck';
			case 'exercises.desc_reverse_pec_deck': return '1. Sit facing the machine. Grab the handles with a slight bend in your elbows.\n2. Exhale and pull your arms wide out to your sides and back.\n3. Squeeze your rear delts and shoulder blades together for 1 second. Inhale and slowly return.';
			case 'exercises.name_romanian_deadlift': return 'Barbell Romanian Deadlift';
			case 'exercises.desc_romanian_deadlift': return '1. Stand holding a barbell against your thighs with a slight knee bend. Keep your chest up.\n2. Inhale, push your hips straight back (hip hinge), and glide the bar down your legs until your hamstrings fully stretch.\n3. Exhale, squeeze your glutes, and push your hips forward to stand tall.';
			case 'exercises.name_russian_twist': return 'Russian Twist';
			case 'exercises.desc_russian_twist': return '1. Sit on the floor, lean back into a V-shape, and lift your feet off the ground.\n2. Exhale and forcefully twist your torso to the right side.\n3. Inhale as you return to the center, then exhale and twist to the left.';
			case 'exercises.name_seated_cable_row_vgrip': return 'Seated Cable Row (V-Grip)';
			case 'exercises.desc_seated_cable_row_vgrip': return '1. Sit at the machine with your feet on the platforms, knees slightly bent, and grasp the V-bar.\n2. Keep your back straight, chest up, and pull the handle toward your belly button while keeping your elbows tucked close to your body.\n3. Squeeze your mid-back at the peak contraction, then slowly return to the starting position to stretch your lats.';
			case 'exercises.name_seated_cable_row_widegrip': return 'Seated Cable Row (Wide Grip)';
			case 'exercises.desc_seated_cable_row_widegrip': return '1. Sit at the machine and grasp the wide bar with an overhand grip, hands wider than shoulder-width.\n2. Keep your chest up and pull the bar toward your lower chest/upper stomach, flaring your elbows slightly outward.\n3. Squeeze your shoulder blades together to target the upper back and rear delts, then slowly extend your arms back.';
			case 'exercises.name_seated_calf_raise': return 'Seated Calf Raise';
			case 'exercises.desc_seated_calf_raise': return '1. Sit at the machine with the pads resting on your lower thighs.\n2. Inhale and lower your heels as far as possible to stretch your calves.\n3. Exhale and drive through the balls of your feet to raise your heels as high as possible. Hold for 1 second.';
			case 'exercises.name_skull_crushers': return 'Skullcrusher';
			case 'exercises.desc_skull_crushers': return '1. Lie flat on a bench pressing a barbell up. Angle your upper arms slightly backward toward your head (15 degrees).\n2. Inhale and bend your elbows to lower the bar toward your forehead.\n3. Exhale and extend your elbows forcefully to return the bar to the top.';
			case 'exercises.name_stair_climber': return 'Stair Climber';
			case 'exercises.desc_stair_climber': return '1. Step rhythmically onto the moving stairs.\n2. Place your entire foot on the step and push through your heels to maximally engage your glutes.';
			case 'exercises.name_standing_calf_raise': return 'Standing Calf Raise';
			case 'exercises.desc_standing_calf_raise': return '1. Stand with the balls of your feet on a raised platform. Inhale and let your heels drop to get a deep stretch.\n2. Exhale and raise your heels as high as possible. Keep your knees straight but not locked.\n3. Hold the contraction for 1-2 seconds, then lower slowly.';
			case 'exercises.name_superman': return 'Superman';
			case 'exercises.desc_superman': return '1. Lie face down on a mat with arms and legs fully extended.\n2. Squeeze your lower back and simultaneously lift your arms, chest, and legs off the floor.\n3. Hold the top position for 2-3 seconds, breathing shallowly, then lower back down.';
			case 'exercises.name_treadmill': return 'Treadmill';
			case 'exercises.desc_treadmill': return '1. Start the belt at a slow speed before stepping on.\n2. Adjust the Speed and Incline to match your workout goals.\n3. Keep your posture upright, look forward, and pump your arms rhythmically.';
			case 'exercises.name_tricep_pushdown': return 'Triceps Pushdown';
			case 'exercises.desc_tricep_pushdown': return '1. Stand at a high cable pulley. Pin your elbows tightly against your ribs.\n2. Exhale and push the bar/rope straight down until your arms are fully locked out.\n3. Inhale and slowly let the cable pull your forearms back up without moving your elbows.';
			case 'exercises.name_upright_row': return 'Upright Row';
			case 'exercises.desc_upright_row': return '1. Hold a barbell with a narrow grip resting against your thighs.\n2. Exhale and pull the bar straight up to your chin, leading with your elbows. Your elbows must always be higher than your wrists.\n3. Hold for 1 second at the top, then inhale and lower straight down.';
			case 'exercises.name_warm_up': return 'Warm up';
			case 'exercises.desc_warm_up': return 'Thoroughly rotate your wrists, ankles, shoulders, hips, and knees for 5-10 minutes to lubricate the joints and raise your heart rate.';
			case 'exercises.name_cable_crossover': return 'Cable Crossover';
			case 'exercises.desc_cable_crossover': return '1. Stand between high pulleys. Open your arms with a slight, locked bend in your elbows.\n2. Exhale and pull the handles together, crossing them over each other in front of your chest.\n3. Squeeze your chest hard for 1 second, then inhale and slowly open your arms.';
			case 'exercises.name_pec_deck_fly': return 'Pec Deck Fly';
			case 'exercises.desc_pec_deck_fly': return '1. Sit in the Pec Deck machine with arms spread wide. Inhale to stretch the chest.\n2. Exhale and squeeze your arms together in front of your chest.\n3. Hold the contraction for 1 second, then inhale and slowly let the arms open back up.';
			case 'exercises.name_t_bar_row': return 'T-Bar Row';
			case 'exercises.desc_t_bar_row': return '1. Bend over, straddling the T-bar. Keep your back naturally straight.\n2. Exhale, pull the bar forcefully toward your chest/stomach, and squeeze your shoulder blades together.\n3. Inhale and lower the bar under control to fully stretch your back.';
			case 'exercises.name_preacher_curl': return 'Preacher Curl';
			case 'exercises.desc_preacher_curl': return '1. Sit at a Preacher bench, locking your upper arms firmly into the pad. Hold a barbell with an underhand grip.\n2. Exhale and curl the weight toward your chin, squeezing your biceps.\n3. Inhale and lower the weight slowly until your arms are almost fully extended.';
			case 'exercises.name_hack_squat': return 'Hack Squat';
			case 'exercises.desc_hack_squat': return '1. Position your back flat against the Hack Squat pad. Inhale and bend your knees to lower the sled.\n2. Descend until your thighs are parallel to the footplate.\n3. Exhale and drive forcefully through your heels to push the sled back up.';
			case 'exercises.name_seated_leg_curl': return 'Seated Leg Curl';
			case 'exercises.desc_seated_leg_curl': return '1. Sit in the machine with the ankle pad locked just above your heels.\n2. Exhale and curl your legs down under the seat as far as possible.\n3. Inhale and slowly return the pad upwards without letting the weight stack touch.';
			case 'exercises.name_overhead_cable_triceps': return 'Overhead Cable Triceps Extension';
			case 'exercises.desc_overhead_cable_triceps': return '1. Attach a rope to a low pulley of a cable machine. Stand facing away from the machine, grasp the rope with both hands, and pull it overhead so it rests behind your neck, with elbows pointing up.\n2. Exhale and extend both arms straight overhead, keeping your elbows locked close to your head.\n3. Inhale and slowly lower the rope back to the starting position behind your neck in a controlled manner.';
			case 'exercises.name_seated_wrist_curl': return 'Seated Wrist Curl';
			case 'exercises.desc_seated_wrist_curl': return '1. Sit with your forearms resting on your thighs, holding a dumbbell or barbell palms up.\n2. Let the weight roll down to your fingertips to stretch the forearms. Exhale and forcefully curl your wrists upward.\n3. Inhale and slowly lower the weight back down.';
			case 'exercises.name_chest_supported_row': return 'Chest-Supported Row';
			case 'exercises.desc_chest_supported_row': return '1. Lie face down on a 45-degree incline bench with your chest supported. Let dumbbells hang straight down.\n2. Exhale, pull your elbows up to the ceiling, and squeeze your shoulder blades.\n3. Inhale and slowly lower the dumbbells to stretch your back.';
			case 'exercises.name_single_arm_lat_pulldown': return 'Single Arm Lat Pulldown';
			case 'exercises.desc_single_arm_lat_pulldown': return '1. Sit at a high pulley holding a D-handle with one hand. Puff your chest up.\n2. Exhale and pull your elbow straight down into your side.\n3. Squeeze your lat at the bottom for 1 second, then inhale and slowly release the cable.';
			case 'exercises.name_smith_machine_squat': return 'Smith Machine Squat';
			case 'exercises.desc_smith_machine_squat': return '1. Place the Smith machine bar across your shoulders. Position your feet slightly further forward than a free-weight squat.\n2. Inhale, push your hips back, and squat down to parallel.\n3. Exhale and drive through your heels to stand back up.';
			case 'exercises.name_hip_adduction': return 'Hip Adduction Machine';
			case 'exercises.desc_hip_adduction': return '1. Sit in the inner thigh machine with your legs spread open against the pads.\n2. Exhale and squeeze your thighs together to close the pads.\n3. Hold for 1 second. Inhale and slowly let your legs open under control.';
			case 'exercises.name_hip_abduction': return 'Hip Abduction Machine';
			case 'exercises.desc_hip_abduction': return '1. Sit in the outer thigh machine with your legs closed against the pads.\n2. Exhale and push your knees outward as far as possible using your glutes.\n3. Hold the squeeze for 1 second. Inhale and slowly bring your legs back together.';
			case 'exercises.name_seated_incline_curl': return 'Incline Dumbbell Curl';
			case 'exercises.desc_seated_incline_curl': return '1. Sit on a 45-60 degree incline bench, letting your arms hang straight down behind your torso.\n2. Keep your upper arms completely still. Exhale, curl the dumbbells up to your shoulders, and turn your palms up.\n3. Inhale and slowly lower the weights down to a full stretch.';
			case 'exercises.name_shoulder_press_machine': return 'Machine Shoulder Press';
			case 'exercises.desc_shoulder_press_machine': return '1. Sit in the machine and grab the handles at shoulder level.\n2. Exhale and press the handles straight up overhead without locking out your elbows.\n3. Inhale and control the handles as they lower back to the starting position.';
			case 'exercises.name_crunch_machine': return 'Machine Crunch';
			case 'exercises.desc_crunch_machine': return '1. Lock yourself into the ab crunch machine. Inhale deeply.\n2. Exhale and crunch your torso forward, contracting your abs hard.\n3. Hold the bottom position for 1 second, then inhale and slowly return to an upright position.';
			case 'programs.ppl_gym_beg_name': return 'Push Pull Legs - Beginner (Gym)';
			case 'programs.ppl_gym_beg_desc': return 'Ideal roadmap to get used to a 3-day-per-week training rhythm using safe fixed machines. This routine helps beginners build a solid muscular foundation, grasp proper technique, and minimize injury risk in the early stages.';
			case 'programs.ppl_gym_int_name': return 'Push Pull Legs - Intermediate (Gym)';
			case 'programs.ppl_gym_int_desc': return 'Elevate the challenge with a 6-day-per-week intensity flexibly combining barbells and dumbbells. Focuses on increasing overall training volume, stimulating balanced muscle growth, and visibly improving foundational strength.';
			case 'programs.ppl_gym_adv_name': return 'Push Pull Legs - Advanced (Gym)';
			case 'programs.ppl_gym_adv_desc': return 'Push your body past its limits with an extremely high-intensity 6-day routine. Maximizes heavy loads on compound movements and refines muscle details through isolation exercises, specifically designed to break plateaus and drive maximum muscle growth.';
			case 'programs.ppl_db_beg_name': return 'Push Pull Legs - Beginner (Dumbbell)';
			case 'programs.ppl_db_beg_desc': return 'Start your physique transformation journey at home with just 3 days a week and a pair of dumbbells. This routine offers maximum convenience, helping beginners easily access resistance training safely and effectively in their own space.';
			case 'programs.ppl_db_int_name': return 'Push Pull Legs - Intermediate (Dumbbell)';
			case 'programs.ppl_db_int_desc': return 'Fully exploit the potential of dumbbells with a challenging 6-day-per-week schedule. By varying movement angles and increasing sets, this routine ensures muscles continuously receive strong growth signals even when training at home.';
			case 'programs.ppl_db_adv_name': return 'Push Pull Legs - Advanced (Dumbbell)';
			case 'programs.ppl_db_adv_desc': return 'Apply advanced training techniques and push muscles to exhaustion with 6 days a week using dumbbells. Requires intense focus, maximizing free-weight efficiency to sculpt a sharp and detailed physique.';
			case 'programs.ul_gym_beg_name': return 'Upper Lower - Beginner (Gym)';
			case 'programs.ul_gym_beg_desc': return 'Divide the body into upper and lower halves with a 4-day-per-week rhythm. This smart structure provides optimal rest periods, helping beginners recover fully while maintaining necessary stimulation for muscle growth.';
			case 'programs.ul_gym_int_name': return 'Upper Lower - Intermediate (Gym)';
			case 'programs.ul_gym_int_desc': return 'Shift focus to heavy multi-joint barbell exercises across 4 days a week. This routine is the key to increasing explosive power, driving muscle size, and creating a leap in body mass.';
			case 'programs.ul_gym_adv_name': return 'Upper Lower - Advanced (Gym)';
			case 'programs.ul_gym_adv_desc': return 'Face a massive training volume and relentless progressive overload meant for seasoned lifters. This 4-day schedule optimizes neural endurance and maximally activates fast-twitch muscle fibers.';
			case 'programs.ul_db_beg_name': return 'Upper Lower - Beginner (Dumbbell)';
			case 'programs.ul_db_beg_desc': return 'A streamlined and highly effective 4-day home routine using dumbbells. This schedule equally divides focus between upper and lower body, helping you build a solid physical foundation without spending too much time.';
			case 'programs.ul_db_int_name': return 'Upper Lower - Intermediate (Dumbbell)';
			case 'programs.ul_db_int_desc': return 'Challenge muscle endurance at home with high-intensity dumbbell variations over 4 days a week. The structure is scientifically arranged to ensure continuous stimulation, visibly transforming your physique week by week.';
			case 'programs.ul_db_adv_name': return 'Upper Lower - Advanced (Dumbbell)';
			case 'programs.ul_db_adv_desc': return 'A brutally strict dumbbell schedule requiring absolute discipline. Optimizes time under tension to create an ideal growth environment, delivering muscle-building results that rival professional gym training.';
			case 'programs.fb_gym_beg_name': return 'Full Body - Beginner (Gym)';
			case 'programs.fb_gym_beg_desc': return 'Activate all major muscle groups in a single session with a frequency of 2-3 times per week. The perfect stepping stone to introduce beginners to resistance, optimizing time while mastering basic movement techniques.';
			case 'programs.fb_gym_int_name': return 'Full Body - Intermediate (Gym)';
			case 'programs.fb_gym_int_desc': return 'A 3-day-per-week routine inspired by professional strength athletes. Focuses heavily on heavyweight barbell exercises to fire up the central nervous system, resulting in superior foundational strength and dense muscle mass.';
			case 'programs.fb_gym_adv_name': return 'Full Body - Advanced (Gym)';
			case 'programs.fb_gym_adv_desc': return 'Requires incredible stamina with 3 horrifyingly intense sessions per week. This routine constantly challenges both neural and full-body muscular endurance, designed to shatter the physical limits of veteran lifters.';
			case 'programs.fb_db_beg_name': return 'Full Body - Beginner (Dumbbell)';
			case 'programs.fb_db_beg_desc': return 'A comprehensive, time-saving home workout solution using just a pair of dumbbells. Wakes up every muscle group through fundamental movements, perfect for busy individuals wanting to maintain an active habit.';
			case 'programs.fb_db_int_name': return 'Full Body - Intermediate (Dumbbell)';
			case 'programs.fb_db_int_desc': return 'Elevate overall fitness by increasing volume and incorporating diverse dumbbell exercises. Ensures the entire body is trained evenly, bringing about tone, fat loss, and significant cardiovascular improvements.';
			case 'programs.fb_db_adv_name': return 'Full Body - Advanced (Dumbbell)';
			case 'programs.fb_db_adv_desc': return 'Exhaust the entire body using slow, controlled tempos and peak dumbbell intensity. Forces every muscle fiber to engage, delivering muscle-building and shredding results far beyond expectations.';
			case 'programs.fb_bw_beg_name': return 'Full Body - Beginner (Bodyweight)';
			case 'programs.fb_bw_beg_desc': return 'Use your own body weight as resistance to train balance and strengthen the core. A gentle, easily accessible routine for any space, helping you build discipline without investing in complex equipment.';
			case 'programs.fb_bw_int_name': return 'Full Body - Intermediate (Bodyweight)';
			case 'programs.fb_bw_int_desc': return 'Increase the challenge through complex bodyweight exercise variations. This routine not only burns massive energy but also develops agility, flexibility, and spatial body control.';
			case 'programs.fb_bw_adv_name': return 'Full Body - Advanced (Bodyweight)';
			case 'programs.fb_bw_adv_desc': return 'A journey of primal strength training through advanced calisthenics movements like pull-ups, dips, and hard-to-control variations. Requires a perfect blend of raw power, balance, and absolute core strength.';
			case 'programs.combo_gym_beg_name': return 'PPL & Upper/Lower - Beginner (Gym)';
			case 'programs.combo_gym_beg_desc': return 'Creates a gentle transitional stepping stone with 3 days a week for the body to adapt before moving to the intensive 5-day hybrid routine. Helps build a solid foundation and physical readiness for harsher challenges.';
			case 'programs.combo_gym_int_name': return 'PPL & Upper/Lower - Intermediate (Gym)';
			case 'programs.combo_gym_int_desc': return 'The 5-day structure provides the perfect balance between muscle hypertrophy goals and maximal strength gains. Smart rotation between workout days optimizes recovery capacity and prevents overtraining.';
			case 'programs.combo_gym_adv_name': return 'PPL & Upper/Lower - Advanced (Gym)';
			case 'programs.combo_gym_adv_desc': return 'The pinnacle of workout programming with 5 of the most grueling sessions. Tailored specifically for seasoned individuals who want to force their bodies into continuous stress to achieve physical perfection.';
			case 'programs.combo_db_beg_name': return 'PPL & Upper/Lower - Beginner (Dumbbell)';
			case 'programs.combo_db_beg_desc': return 'A hybrid dumbbell version over 3 days a week acting as a primer. Gentle and easy to execute, but still provides enough stimulus for muscles to recognize the need for change and begin a stronger rebuilding process.';
			case 'programs.combo_db_int_name': return 'PPL & Upper/Lower - Intermediate (Dumbbell)';
			case 'programs.combo_db_int_desc': return 'A scientifically split 5-day home routine. Maximizes dumbbell utility to deliver clear physique development while still leaving enough time for muscle groups to rest and grow.';
			case 'programs.combo_db_adv_name': return 'PPL & Upper/Lower - Advanced (Dumbbell)';
			case 'programs.combo_db_adv_desc': return 'Challenge every limit of endurance at home with a relentless 5-day rotating schedule. By pushing dumbbell intensity to the max, this routine drains energy and forces the body to adapt by growing bigger and stronger.';
			case 'programs.cardio_gym_int_name': return 'Fat Burning Cardio & HIIT (Gym)';
			case 'programs.cardio_gym_int_desc': return 'A cardiovascular training system with continuously varying, powerful intensities. Strongly emphasizes massive calorie burn, eliminating stubborn fat, and elevating endurance to a completely new standard.';
			case 'routines.push_1': return 'Push 1';
			case 'routines.push_2': return 'Push 2';
			case 'routines.pull_1': return 'Pull 1';
			case 'routines.pull_2': return 'Pull 2';
			case 'routines.legs_1': return 'Legs 1';
			case 'routines.legs_2': return 'Legs 2';
			case 'routines.upper_1': return 'Upper 1';
			case 'routines.upper_2': return 'Upper 2';
			case 'routines.lower_1': return 'Lower 1';
			case 'routines.lower_2': return 'Lower 2';
			case 'routines.full_1': return 'Full Body 1';
			case 'routines.full_2': return 'Full Body 2';
			case 'routines.full_3': return 'Full Body 3';
			case 'routines.cardio_1': return 'Cardio 1';
			case 'routines.cardio_2': return 'Cardio 2';
			case 'routines.hiit_1': return 'HIIT 1';
			case 'routines.hiit_2': return 'HIIT 2';
			case 'tour.library_add_custom_title': return 'Custom Exercise';
			case 'tour.library_add_custom_desc': return 'Can\'t find your exercise? Create a custom one here to fit your needs.';
			case 'tour.log_timer_play_title': return 'Smart Timer';
			case 'tour.log_timer_play_desc': return 'Tap the time to adjust:\n• Start from 00:00 ➔ Stopwatch\n• Set a specific time ➔ Countdown\n\nThe mode locks once started. You can select a new time to reset it.';
			case 'tour.workout_explore_desc': return 'Tap here to explore and add professional workout Programs to your list.';
			case 'tour.workout_recovery_desc': return 'Monitor the time and level of recovery for your muscle groups after workouts to optimize effectiveness.';
			case 'tour.workout_folder_title': return 'Routine Management';
			case 'tour.workout_folder_desc': return 'Use this section to manage and organize your workout routines.';
			case 'tour.workout_folder_add_btn_title': return 'Add Folder';
			case 'tour.workout_folder_smart_empty_desc': return 'Tap here to create a new empty folder to organize your routines.';
			case 'tour.nutrition_history_title': return 'Nutrition History';
			case 'tour.nutrition_history_desc': return 'Review your past meals and track your long-term progress here.';
			case 'tour.nutrition_dashboard_title': return 'Nutrition Dashboard';
			case 'tour.nutrition_dashboard_desc': return 'Track Calories and Macros.\nTip: Tap this card to customize your daily goals!';
			case 'tour.nutrition_water_title': return 'Water Tracker';
			case 'tour.nutrition_water_desc': return 'Stay hydrated!\nTip: Tap the card to set a target, or use +/- to log your intake.';
			case 'tour.nutrition_weight_title': return 'Weight Goal';
			case 'tour.nutrition_weight_desc': return 'Track your progress.\nTip: Tap \'Update\' to log your current weight, or the edit icon to edit your goal!';
			case 'tour.nutrition_meal_title': return 'Meal Log';
			case 'tour.nutrition_meal_desc': return 'Log your daily meals.\nTip: Tap \'Add food\', or use the Copy icon to quickly duplicate yesterday\'s data!';
			case 'tour.calendar_toggle_title': return 'View Mode';
			case 'tour.calendar_toggle_desc': return 'Tap to switch between Month, Year, or Multi-Year calendar views.';
			case 'tour.calendar_day_title': return 'Logs & Schedule';
			case 'tour.calendar_day_desc': return 'Tap to view past workouts or schedule new routines in the future.';
			case 'tour.log_minimize_title': return 'Minimize Workout';
			case 'tour.log_minimize_desc': return 'When you press this button or exit the workout, the data will still run in the background so you can view other screens without affecting your workout progress!';
			case 'tour.log_dashboard_title': return 'Statistics Dashboard';
			case 'tour.log_dashboard_desc': return 'Use this to track time and statistics related to metrics like total load, total exercises, total sets,...';
			case 'tour.log_exercise_options_title': return 'Exercise Options';
			case 'tour.log_exercise_options_desc': return 'Tap here to replace exercises, change order, combine Supersets, or remove exercises from the workout.';
			case 'tour.log_set_row_title': return 'Log Set';
			case 'tour.log_set_row_desc': return 'Enter your workout data and tap the circle to complete the set. The rest timer will automatically start afterward!';
			case 'tour.log_fab_add_title': return 'Expand';
			case 'tour.log_fab_add_desc': return 'Tap here to add new exercises, change order of exercises, or cancel the workout.';
			
		}
	}
}

extension on _StringsVi {
	dynamic _flatMapFunction(String path) {
		switch (path) {
			case 'app_name': return 'Plato';
			case 'company_name': return 'Zenithas';
			case 'common.tutorial_title': return 'Hướng dẫn sử dụng';
			case 'common.video_error': return 'Không thể tải video hướng dẫn';
			case 'common.about_us': return 'Về chúng tôi';
			case 'common.skip': return 'Bỏ qua';
			case 'common.logout': return 'Đăng xuất';
			case 'common.save': return 'Lưu';
			case 'common.cancel': return 'Hủy';
			case 'common.close': return 'Đóng';
			case 'common.delete': return 'Xóa';
			case 'common.decline': return 'Từ chối';
			case 'common.accept': return 'Cho phép';
