			case 'onboarding.terms_p2_desc3': return 'Cam kết thương mại: Chúng tôi không chia sẻ, bán hoặc cung cấp dữ liệu cá nhân của bạn cho bất kỳ bên thứ ba nào vì mục đích thương mại hay quảng cáo.';
			case 'onboarding.terms_p3_title': return '3. Lưu trữ và Bên thứ ba cung cấp dịch vụ';
			case 'onboarding.terms_p3_desc1': return 'Lưu trữ cục bộ (SQLite): Một phần dữ liệu và cài đặt cá nhân được lưu trữ trực tiếp trên thiết bị của bạn để đảm bảo tốc độ truy xuất và khả năng hoạt động ngoại tuyến (offline). Dữ liệu chỉ được đồng bộ lên hệ thống đám mây khi có kết nối mạng.';
			case 'onboarding.terms_p3_desc2': return ({required Object brand}) => 'Dịch vụ hạ tầng (Supabase): Chúng tôi sử dụng ${brand} để lưu trữ cơ sở dữ liệu và xác thực người dùng. Dữ liệu được mã hóa an toàn khi truyền tải (in transit) và khi lưu trữ (at rest) theo tiêu chuẩn quốc tế.';
			case 'onboarding.terms_p3_desc3': return 'Bảo mật dữ liệu: Chúng tôi áp dụng Row Level Security (RLS) để đảm bảo mỗi người dùng chỉ có thể truy cập vào dữ liệu của chính mình.';
			case 'onboarding.terms_p4_title': return '4. Quyền kiểm soát của người dùng';
			case 'onboarding.terms_p4_desc1': return 'Tuân thủ Nghị định 13/2023 (VN) và luật quốc tế, bạn có toàn quyền đối với dữ liệu cá nhân của mình:\n• Quyền chỉnh sửa: Bạn có thể thay đổi thông tin cá nhân trong phần Profile bất kỳ lúc nào.\n• Quyền xóa bỏ: Bạn có quyền yêu cầu "Xóa tài khoản". Khi đó, toàn bộ dữ liệu liên kết với email của bạn sẽ được xóa sạch khỏi Database hoặc ẩn danh hóa hoàn toàn.';
			case 'onboarding.terms_p5_title': return '5. Dịch vụ và Trách nhiệm hệ thống';
			case 'onboarding.terms_p5_desc1': return ({required Object app}) => 'Tính chất dịch vụ: ${app} cung cấp toàn bộ tính năng hiện có miễn phí. Chúng tôi bảo lưu quyền thay đổi mô hình kinh doanh hoặc thêm các tính năng cao cấp trong tương lai và sẽ thông báo trước cho người dùng.';
			case 'onboarding.terms_p5_desc2': return ({required Object brand}) => 'Giới hạn trách nhiệm: Trong phạm vi pháp luật cho phép, ${brand} không chịu trách nhiệm cho các thiệt hại phát sinh từ việc sử dụng ứng dụng hoặc các lỗi kỹ thuật, mất mát dữ liệu do sự cố bất khả kháng.';
			case 'onboarding.title_eula': return ({required Object app}) => 'THỎA THUẬN CẤP PHÉP NGƯỜI DÙNG CUỐI (${app})';
			case 'onboarding.eula_updated': return 'Cập nhật lần cuối: Tháng 4/2026';
			case 'onboarding.eula_intro': return ({required Object brand, required Object app}) => 'Thỏa thuận này là hợp đồng pháp lý giữa bạn (Người dùng) và ${brand} (Chúng tôi) về việc sử dụng ứng dụng di động ${app}. Bằng việc cài đặt hoặc sử dụng ứng dụng, bạn đồng ý tuân thủ các điều khoản sau:';
			case 'onboarding.eula_p1_title': return '1. Cấp phép sử dụng';
			case 'onboarding.eula_p1_desc': return ({required Object app}) => 'Chúng tôi cấp cho bạn một giấy phép giới hạn, không độc quyền, không thể chuyển nhượng và có thể thu hồi để tải xuống, cài đặt và sử dụng ${app} trên các thiết bị di động thuộc quyền sở hữu của bạn, phục vụ cho mục đích cá nhân và không thương mại.';
			case 'onboarding.eula_p2_title': return '2. Quyền sở hữu trí tuệ';
			case 'onboarding.eula_p2_desc1': return ({required Object app}) => 'Toàn bộ quyền, danh nghĩa và lợi ích đối với ứng dụng ${app}, bao gồm nhưng không giới hạn ở:';
			case 'onboarding.eula_p2_item1': return '• Công nghệ: Các thuật toán tính toán mức độ nỗ lực (RPE), logic đánh giá độ sẵn sàng của cơ bắp (Muscle Readiness).';
			case 'onboarding.eula_p2_item2': return ({required Object brand, required Object app}) => '• Thiết kế: Giao diện người dùng (UI), trải nghiệm người dùng (UX), logo ${brand} và biểu tượng ${app}.';
			case 'onboarding.eula_p2_item3': return '• Nội dung: Các gói tập mẫu, dữ liệu hướng dẫn và cấu trúc biểu đồ.';
			case 'onboarding.eula_p2_desc2': return ({required Object brand}) => 'Tất cả đều là tài sản trí tuệ độc quyền của ${brand}. Mọi hành vi sao chép hoặc sử dụng trái phép đều vi phạm pháp luật.';
			case 'onboarding.eula_p3_title': return '3. Các hành vi bị nghiêm cấm';
