			case 'onboarding.eula_p3_item2': return ({required Object app}) => '• Sao chép các công thức tính toán và logic phục hồi của ${app} để xây dựng sản phẩm cạnh tranh.';
			case 'onboarding.eula_p3_item3': return '• Sử dụng ứng dụng cho bất kỳ mục đích bất hợp pháp hoặc vi phạm các tuyên bố về an toàn y tế.';
			case 'onboarding.eula_p4_title': return '4. Dữ liệu và Quyền riêng tư';
			case 'onboarding.eula_p4_desc': return 'Việc sử dụng ứng dụng của bạn cũng tuân theo Chính sách bảo mật của chúng tôi. Bạn hiểu rằng dữ liệu sẽ được lưu trữ cục bộ (SQLite) và đồng bộ hóa qua dịch vụ đám mây để đảm bảo trải nghiệm tốt nhất. Bạn có quyền yêu cầu xóa tài khoản và toàn bộ dữ liệu liên quan bất cứ lúc nào.';
			case 'onboarding.eula_p5_title': return '5. Giới hạn trách nhiệm và Miễn trừ y tế';
